process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import fs from 'fs';
import { execSync } from 'child_process';
import { chromium } from 'playwright';
const B='https://dev.avesa.lt';
const U=process.env.WP_USER,P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='Basic '+Buffer.from(U+':'+P).toString('base64');
const TOK=process.env.GH_TOKEN||'';
fs.mkdirSync('screenshots',{recursive:true});
const out={marker:'RINK APPLY v1',ts:new Date().toISOString()};
async function wp(p,o={}){try{const r=await fetch(B+p,{...o,headers:{'Authorization':AUTH,'Content-Type':'application/json',...(o.headers||{})}});return{status:r.status,text:await r.text()}}catch(e){return{status:0,text:String(e)}}}
function js(t){const i=Math.min(...['[','{'].map(c=>{const x=t.indexOf(c);return x<0?1e9:x}));try{return JSON.parse(t.slice(i))}catch(e){return null}}

// 1) deploy snippet
const php1=Buffer.from('','base64').toString('utf8');
const s1=await wp('/wp-json/code-snippets/v1/snippets',{method:'POST',body:JSON.stringify({name:'TEMP Rink Apply v14',code:php1,scope:'global',active:true,priority:5})});
const j1=js(s1.text); out.snip_deploy=j1&&j1.id?j1.id:null;
// 2) autologin snippet
const php2=Buffer.from('','base64').toString('utf8');
const s2=await wp('/wp-json/code-snippets/v1/snippets',{method:'POST',body:JSON.stringify({name:'TEMP Rink Autologin v1',code:php2,scope:'global',active:true,priority:5})});
const j2=js(s2.text); out.snip_auto=j2&&j2.id?j2.id:null;
await new Promise(r=>setTimeout(r,3500));

// 3) irasom faila
fs.writeFileSync('/tmp/payload.txt','turinys='+encodeURIComponent(''));
try{
  const res=execSync(`curl -sk -X POST "${B}/?ps_deploy=Dp77Kk3&apply=1" --data @/tmp/payload.txt --max-time 150`,{encoding:'utf8',maxBuffer:20*1024*1024});
  out.deploy=js(res)||res.slice(0,1500);
}catch(e){ out.deploy_err=String(e).slice(0,400); }

// 4) ekranai
const files=[];
try{
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true,viewport:{width:1600,height:1150}});
  const pg=await ctx.newPage();
  const errs=[]; pg.on('pageerror',e=>errs.push(String(e).slice(0,160)));
  const tikrinti=async(to,zyme)=>{
    await pg.goto(`${B}/?ps_auto=Qz7Rk88&u=${encodeURIComponent(U)}&to=${encodeURIComponent(to)}`,{waitUntil:'domcontentloaded',timeout:60000});
    await pg.waitForTimeout(3500);
    const info=await pg.evaluate(()=>({
      url:location.href,title:document.title,
      h1:(document.querySelector('.wrap h1')||{}).textContent||'',
      eiles:[...document.querySelectorAll('.psr-eile')].map(e=>e.textContent.replace(/\s+/g,' ').trim()),
      eil:document.querySelectorAll('.psr-lentele tbody tr').length,
      pirma:(document.querySelector('.psr-lentele tbody tr')||{}).innerText||'',
      meniu:[...document.querySelectorAll('#adminmenu a')].map(a=>a.textContent.trim()).filter(t=>/Rinkin|Akcij|Gavim|Katalog/i.test(t)),
      fatal:/Fatal error|Parse error|Warning:/i.test(document.body.innerText)?document.body.innerText.slice(0,400):'',
      forma:{kort:document.querySelectorAll('.psr-kort').length,
             filtrai:document.querySelectorAll('.psr-filtrai select').length,
             juosta:!!document.querySelector('.psr-juosta'),
             publ:!!document.getElementById('psr-publikuoti')}
    }));
    const f=`screenshots/rink_${zyme}.png`;
    await pg.screenshot({path:f,fullPage:true}); files.push(f);
    return info;
  };
  out.sarasas=await tikrinti('admin.php?page=ps-rinkiniai','sarasas');
  out.forma=await tikrinti('admin.php?page=ps-rinkiniai&veiksmas=naujas','forma');
  out.js_klaidos=errs;
  await br.close();
}catch(e){ out.browser_err=String(e).slice(0,400); }

for(const id of [out.snip_deploy,out.snip_auto]){ if(id){ await wp('/wp-json/code-snippets/v1/snippets/'+id,{method:'POST',body:JSON.stringify({active:false})}); } }
out.snip_deact='done';
async function put(p,buf,m){const r=await fetch('https://api.github.com/repos/raimis079-creator/petshop-bridge/contents/'+p,{method:'PUT',headers:{'Authorization':'Bearer '+TOK,'Content-Type':'application/json','User-Agent':'b'},body:JSON.stringify({message:m,content:buf.toString('base64')})});return r.status}
for(const f of files){ console.log(f,await put(f,fs.readFileSync(f),'rink shot')); }
console.log('info',await put('screenshots/rink_apply.json',Buffer.from(JSON.stringify(out,null,1)),'rinkrec result apply'));
